-- Chunk 1/9 (50 outils)
BEGIN;

UPDATE tools SET long_description = E'Skribble, c''est signature électronique qualifiée européenne. À partir de 12€/mois.\n\nCe qui distingue Skribble : 3 niveaux de signature (SES, AES, QES). Ajoutez à ça conformité suisse et européenne, et interface moderne et simple. Pour les usages intensifs : intégrations API et no-code. Cas d''usage typique : signer des contrats transfrontaliers CH/UE. On l''utilise aussi pour obtenir des signatures qualifiées sans déplacement.\n\nÀ garder si : activité en Suisse ou avec des clients suisses ou besoin de signature qualifiée. À éviter si : marché uniquement français ou volume faible. Point de friction : prix élevé pour la signature qualifiée. Pertinent si vous traitez avec la Suisse ou avez besoin de QES.', long_description_en = E'Skribble is qualified European electronic signature. Starting at €12/month.' WHERE slug = 'skribble';
UPDATE tools SET long_description = E'Loom, c''est la vidéo asynchrone pour éviter les réunions. À partir de 15.59€/mois. Particulièrement pertinent pour les consultants B2B et les developpeur-solo.\n\nCe qui distingue Loom : enregistrement ultra-rapide : un clic et c''est parti. Ajoutez à ça lien de partage instantané, pas besoin de télécharger/uploader, et commentaires avec timestamps pour feedback précis. Pour les usages intensifs : transcription automatique des vidéos. Cas d''usage typique : feedback client : montrer visuellement les modifications à apporter sur un design ou site web. On l''utilise aussi pour onboarding : créer des tutoriels vidéo pour expliquer comment utiliser vos livrables. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : expliquer des bugs ou feedbacks visuels ou remplacer des réunions de statut. À éviter si : vous préférez écrire des longs emails ou vos clients détestent la vidéo. Point de friction : version gratuite limitée à 25 vidéos (puis suppression des anciennes). Dès que vous tapez le même email d''explication pour la 3ème fois.', long_description_en = E'Loom is asynchronous video to avoid meetings. Starting at €15.59/month. Most relevant for B2B consultants and solo developers.\n\nWhat sets Loom apart: ultra-fast recording: one click and you''re ready to go. Add to that instant sharing link, no need to download/upload, and timestamped comments for precise feedback. For power users: automatic video transcription. Typical use case: client feedback: visually show the changes needed on a design or website. Also useful for onboarding: create video tutorials to explain how to use your deliverables. Estimated time saving: 3h/month with regular use.\n\nKeep it if: explaining bugs or visual feedback or replacing status meetings. Skip it if: you prefer writing long emails or your clients hate video. Main friction point: free version limited to 25 videos (then older ones are deleted). As soon as you type the same explanatory email for the 3rd time.' WHERE slug = 'loom';
UPDATE tools SET long_description = E'Process Street, c''est plateforme de gestion de processus pour équipes. À partir de 10€/mois. Particulièrement pertinent pour les consultants B2B et les fondateurs SaaS.\n\nCe qui distingue Process Street : spécialisé en process management, et interface professionnelle. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 10€/mois.', long_description_en = E'Process Street is process management platform for teams. Starting at €10/month. Most relevant for B2B consultants and SaaS founders.\n\nWhat sets Process Street apart: specialized in process management, and professional interface. Estimated time saving: 3h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: price to check depending on usage. As soon as the tool saves you more than €10/month.' WHERE slug = 'process-street';
UPDATE tools SET long_description = E'Heptabase, c''est tableau blanc visuel pour la gestion des connaissances. À partir de 12€/mois.\n\nCe qui distingue Heptabase : organisation visuelle intuitive. Ajoutez à ça cartes et tableaux blancs connectés, et idéal pour la pensée spatiale. Pour les usages intensifs : notes Markdown complètes. Cas d''usage typique : structurer un projet complexe visuellement. On l''utilise aussi pour organiser des notes de recherche spatiales.\n\nÀ garder si : pensée visuelle et spatiale ou organisation de projets complexes. À éviter si : besoin de collaboration d''équipe ou notes simples linéaires. Point de friction : moins adapté au travail collaboratif. Utile si la pensée visuelle est votre mode de réflexion principal.', long_description_en = E'Heptabase is visual whiteboard for knowledge management. Starting at €12/month.' WHERE slug = 'heptabase';
UPDATE tools SET long_description = E'Sellsy, c''est la suite CRM + Facturation française tout-en-un. À partir de 29€/mois. Particulièrement pertinent pour les manager-dsi et les fondateurs SaaS.\n\nGain de temps estimé : 2h/mois pour un usage régulier.\n\nÀ garder si : vous avez une équipe (2+ personnes) ou vous gérez +20 clients actifs avec un pipeline commercial. À éviter si : vous êtes freelance solo (Indy est mieux et moins cher) ou vous n''avez pas besoin de CRM complet. Dès que vous avez un premier employé ou associé ET que vous gérez activement un pipeline commercial. Alternative gratuite à considérer : indy.', long_description_en = E'Sellsy is the French all-in-one CRM + Invoicing suite. Starting at €29/month. Most relevant for manager-dsi and SaaS founders.\n\nEstimated time saving: 2h/month with regular use.\n\nKeep it if: you have a team (2+ people) or you manage +20 active clients with a sales pipeline. Skip it if: you are a solo freelancer (Indy is better and cheaper) or you don''t need a full CRM. As soon as you have your first employee or partner AND you are actively managing a sales pipeline. Free alternative worth considering: indy.' WHERE slug = 'sellsy';
UPDATE tools SET long_description = E'ProductionCrate, c''est bibliothèques numériques pour la création vidéo. À partir de 10€/mois. Particulièrement pertinent pour les graphiste-da et les community-manager.\n\nCe qui distingue ProductionCrate : spécialisé en stock media, et interface professionnelle. Gain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 10€/mois.', long_description_en = E'ProductionCrate is digital libraries for video creation. Starting at €10/month. Most relevant for graphiste-da and community-manager.\n\nWhat sets ProductionCrate apart: specialized in stock media, and professional interface. Estimated time saving: 5h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: price to be verified based on usage. As soon as the tool saves you more than €10/month.' WHERE slug = 'productioncrate';
UPDATE tools SET long_description = E'Sage Paie, c''est solution de paie complète pour PME. À partir de 40€/mois.\n\nCe qui distingue Sage Paie : écosystème Sage complet (compta + paie + gestion). Ajoutez à ça conformité française mise à jour automatiquement, et support téléphonique en français. Pour les usages intensifs : historique et fiabilité de la marque. Cas d''usage typique : produire les bulletins de paie mensuels. On l''utilise aussi pour télédéclarer les charges sociales.\n\nÀ garder si : déjà dans l''écosystème Sage ou pME 10+ salariés. À éviter si : startup cherchant une solution moderne ou freelance. Point de friction : interface vieillissante. Justifié pour les PME 10+ salariés déjà dans l''écosystème Sage.', long_description_en = E'Sage Paie is complete payroll solution for SMEs. Starting at €40/month.' WHERE slug = 'sage-paie';
UPDATE tools SET long_description = E'Shield App, c''est analytics LinkedIn pour créateurs de contenu. À partir de 8€/mois.\n\nCe qui distingue Shield App : analytics LinkedIn détaillés et visuels. Ajoutez à ça historique de performance illimité, et benchmarks et comparaisons. Pour les usages intensifs : rapports exportables. Cas d''usage typique : analyser les performances de ses posts LinkedIn. On l''utilise aussi pour identifier les meilleurs horaires de publication.\n\nÀ garder si : linkedIn est un canal d''acquisition majeur ou publication 3+ fois par semaine. À éviter si : linkedIn occasionnel ou publication < 1 fois par semaine. Point de friction : limité à LinkedIn uniquement. Utile si LinkedIn génère des leads ou de la visibilité business.', long_description_en = E'Shield App is linkedIn analytics for content creators. Starting at €8/month.' WHERE slug = 'shield-app';
UPDATE tools SET long_description = E'Grammarly, c''est votre correcteur d''anglais personnel. À partir de 12€/mois. Particulièrement pertinent pour les newslettiste-auteur et les consultants B2B.\n\nCe qui distingue Grammarly : fonctionne partout via l''extension navigateur. Ajoutez à ça corrections contextuelles intelligentes (pas juste orthographe), et suggestions de ton et de style pour adapter votre message. Pour les usages intensifs : détection de plagiat (version Premium). Cas d''usage typique : emails clients : éviter les fautes dans vos communications professionnelles. On l''utilise aussi pour propositions commerciales : améliorer la clarté et le ton de vos pitchs. Gain de temps estimé : 6h/mois pour un usage régulier.\n\nÀ garder si : vous écrivez quotidiennement en anglais pro ou votre niveau est intermédiaire. À éviter si : vous n''écrivez qu''en français ou vous êtes bilingue natif. Point de friction : version gratuite limitée aux corrections basiques. Dès qu''une faute de grammaire peut vous coûter un contrat ou votre crédibilité. Alternative gratuite à considérer : chatgpt. Si le budget le permet, claude est souvent une meilleure option.', long_description_en = E'Grammarly is your personal English writing assistant. Starting at €12/month. Most relevant for newslettiste-auteur and B2B consultants.\n\nWhat sets Grammarly apart: works everywhere via the browser extension. Add to that intelligent contextual corrections (not just spelling), and tone and style suggestions to adapt your message. For power users: plagiarism detection (Premium version). Typical use case: customer emails: avoid mistakes in your professional communications. Also useful for sales proposals: improve the clarity and tone of your pitches. Estimated time saving: 6h/month with regular use.\n\nKeep it if: you write in professional English on a daily basis or your level is intermediate. Skip it if: vous n''écrivez qu''en français or vous êtes bilingue natif. Main friction point: free version limited to basic corrections. As soon as a grammatical error could cost you a contract or your credibility. Free alternative worth considering: chatgpt. If budget allows, claude is often a better fit.' WHERE slug = 'grammarly';
UPDATE tools SET long_description = E'PushOwl Web Push Notifications, c''est application de notifications push web pour Shopify. À partir de 10€/mois. Particulièrement pertinent pour les ecommercant et les fondateurs SaaS.\n\nCe qui distingue PushOwl Web Push Notifications : spécialisé en web push, et interface professionnelle. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 10€/mois.', long_description_en = E'PushOwl Web Push Notifications is web push notifications app for Shopify. Starting at €10/month. Most relevant for ecommercant and SaaS founders.\n\nWhat sets PushOwl Web Push Notifications apart: specialized in web push, and professional interface. Estimated time saving: 3h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: prix à vérifier selon usage. As soon as the tool saves you more than €10/month.' WHERE slug = 'pushowl-web-push-notifications';
UPDATE tools SET long_description = E'Logseq, c''est pKM open-source avec graphe de connaissances. La version de base est gratuite, avec des options payantes pour aller plus loin.\n\nCe qui distingue Logseq : gratuit et open-source. Ajoutez à ça stockage local en Markdown, et liens bidirectionnels et graphe. Pour les usages intensifs : plugins communautaires riches. Cas d''usage typique : construire un second cerveau local. On l''utilise aussi pour prendre des notes de réunion liées entre elles.\n\nÀ garder si : besoin de notes en réseau sans abonnement ou souveraineté des données importante. À éviter si : besoin de collaboration d''équipe ou préférence pour le cloud natif. Point de friction : performance parfois lente sur les gros graphes. Gratuit — à essayer si Roam Research vous intéresse mais pas son prix.', long_description_en = E'Logseq is open-source PKM with knowledge graph. Core features are free, with paid plans for advanced use.' WHERE slug = 'logseq';
UPDATE tools SET long_description = E'Moss, c''est gestion des dépenses et cartes d''entreprise. À partir de 9€/mois.\n\nCe qui distingue Moss : cartes virtuelles illimitées avec plafonds personnalisables. Ajoutez à ça oCR automatique des reçus, et intégration DATEV, Xero, QuickBooks. Pour les usages intensifs : workflows d''approbation configurables. Cas d''usage typique : gérer les abonnements SaaS avec des cartes dédiées. On l''utilise aussi pour suivre les dépenses d''équipe en temps réel.\n\nÀ garder si : équipe de 3+ personnes avec dépenses récurrentes ou besoin de cartes virtuelles par projet. À éviter si : freelance solo avec peu de frais ou budget serré. Point de friction : prix élevé pour les solopreneurs. Rentable dès 10+ notes de frais par mois.', long_description_en = E'Moss is business expense management and corporate cards. Starting at €9/month.' WHERE slug = 'moss';
UPDATE tools SET long_description = E'Perplexity, c''est le moteur de recherche du futur. À partir de 14.43€/mois. Particulièrement pertinent pour les consultants B2B et les newslettiste-auteur.\n\nCe qui distingue Perplexity : recherche en temps réel avec sources citées. Ajoutez à ça synthèse instantanée au lieu de lire 10 articles, et interface simple et rapide. Pour les usages intensifs : mode Focus pour recherches spécialisées (académique, vidéos, Reddit). Cas d''usage typique : veille : suivre l''actualité de votre secteur avec des synthèses quotidiennes. On l''utilise aussi pour recherche client : comprendre rapidement le marché/concurrence d''un prospect. Gain de temps estimé : 7h/mois pour un usage régulier.\n\nÀ garder si : vous faites beaucoup de recherche documentaire ou vous voulez des sources citées fiables. À éviter si : vous cherchez de la rédaction créative (préférez Claude) ou vous avez besoin d''analyse de données (préférez ChatGPT). Point de friction : parfois moins précis que Google pour des recherches très spécifiques. Dès que vous passez plus de 30 min/jour à chercher des infos techniques.', long_description_en = E'Perplexity is the search engine of the future. Starting at €14.43/month. Most relevant for B2B consultants and newslettiste-auteur.\n\nWhat sets Perplexity apart: real-time search with cited sources. Add to that instant synthesis instead of reading 10 articles, and simple and fast interface. For power users: focus mode for specialized research (academic, videos, Reddit). Typical use case: monitoring: follow your industry news with daily summaries. Also useful for client Research: quickly understand a prospect''s market/competition. Estimated time saving: 7h/month with regular use.\n\nKeep it if: you do a lot of documentary research or you want reliable cited sources. Skip it if: you are looking for creative writing (prefer Claude) or you need data analysis (prefer ChatGPT). Main friction point: sometimes less accurate than Google for very specific searches. As soon as you spend more than 30 minutes a day searching for technical information.' WHERE slug = 'perplexity';
UPDATE tools SET long_description = E'Quadient, c''est solutions d’automatisation des comptes clients et fournisseurs. La version de base est gratuite, avec des options payantes pour aller plus loin. Particulièrement pertinent pour les consultants B2B et les daf-finance.\n\nCe qui distingue Quadient : spécialisé en accounting automation, et interface professionnelle. Gain de temps estimé : 2h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Gratuit, à garder si utile.', long_description_en = E'Quadient is accounts payable and accounts receivable automation solutions. Core features are free, with paid plans for advanced use. Most relevant for B2B consultants and daf-finance.\n\nWhat sets Quadient apart: specialized in accounting automation, and professional interface. Estimated time saving: 2h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: pricing to be verified based on usage. Free, keep it if it''s useful.' WHERE slug = 'quadient';
UPDATE tools SET long_description = E'Coda, c''est doc collaboratif qui fonctionne comme une app. À partir de 10€/mois.\n\nCe qui distingue Coda : formules puissantes façon tableur dans un doc. Ajoutez à ça packs d''intégration (Gmail, Slack, Jira...), et automatisations intégrées sans Zapier. Pour les usages intensifs : templates communautaires riches. Cas d''usage typique : construire un CRM personnalisé. On l''utilise aussi pour automatiser des rapports hebdomadaires.\n\nÀ garder si : besoin de logique métier dans les documents ou construction d''outils internes sans code. À éviter si : usage simple de prise de notes ou équipe non technique. Point de friction : courbe d''apprentissage significative. Justifié si vous construisez des workflows personnalisés au-delà de la simple documentation.', long_description_en = E'Coda is collaborative doc that works like an app. Starting at €10/month.' WHERE slug = 'coda';
UPDATE tools SET long_description = E'SuiteDash, c''est portail client tout-en-un pour agences et freelances. À partir de 19€/mois.\n\nCe qui distingue SuiteDash : tout-en-un : CRM + facturation + projet + portail. Ajoutez à ça portail client personnalisable (white-label), et prix fixe (pas par utilisateur). Pour les usages intensifs : automatisations intégrées. Cas d''usage typique : offrir un portail client professionnel. On l''utilise aussi pour centraliser la facturation et le suivi projet.\n\nÀ garder si : agence ou consultant avec 5+ clients actifs ou besoin d''un portail client brandé. À éviter si : besoin d''un CRM puissant (préférer HubSpot) ou freelance avec 1-2 clients. Point de friction : chaque module moins profond qu''un outil dédié. Rentable si vous remplacez 3+ outils distincts par SuiteDash.', long_description_en = E'SuiteDash is all-in-one client portal for agencies and freelancers. Starting at €19/month.' WHERE slug = 'suitedash';
UPDATE tools SET long_description = E'Make, c''est l''automatisation visuelle sans limite. À partir de 7.79€/mois. Particulièrement pertinent pour les consultants B2B et les developpeur-solo.\n\nCe qui distingue Make : éditeur visuel puissant avec conditions, boucles, gestion d''erreurs. Ajoutez à ça 1000 opérations gratuites par mois (vs 100 chez Zapier), et transformations de données avancées (JSON, XML, formules). Pour les usages intensifs : 1000+ intégrations d''applications. Cas d''usage typique : lead management : automatiser l''ajout de leads depuis des formulaires vers votre CRM. On l''utilise aussi pour content distribution : publier automatiquement vos articles sur LinkedIn, Twitter, Medium. Gain de temps estimé : 8h/mois pour un usage régulier.\n\nÀ garder si : vous voulez connecter vos outils entre eux ou zapier est devenu trop cher. À éviter si : vous avez peur des schémas logiques ou vous n''avez que des besoins très simples (Zapier suffit). Point de friction : courbe d''apprentissage plus raide que Zapier. Dès que vous faites la même tâche manuelle de copier-coller plus de 5 fois par semaine.', long_description_en = E'Make is limitless visual automation. Starting at €7.79/month. Most relevant for B2B consultants and solo developers.\n\nWhat sets Make apart: powerful visual editor with conditions, loops, and error handling. Add to that 1,000 free operations per month (vs 100 with Zapier), and advanced data transformations (JSON, XML, formulas). For power users: 1,000+ app integrations. Typical use case: lead management: automate adding leads from forms to your CRM. Also useful for content distribution: automatically publish your articles on LinkedIn, Twitter, Medium. Estimated time saving: 8h/month with regular use.\n\nKeep it if: you want to connect your tools together or zapier has become too expensive. Skip it if: you are afraid of logic diagrams or you only have very simple needs (Zapier is enough). Main friction point: steeper learning curve than Zapier. As soon as you perform the same manual copy-paste task more than 5 times a week.' WHERE slug = 'make';
UPDATE tools SET long_description = E'Quick Base, c''est plateforme de développement d’applications sans code. À partir de 15€/mois. Particulièrement pertinent pour les manager-dsi et les data-analyst.\n\nCe qui distingue Quick Base : spécialisé en application development, et interface professionnelle. Gain de temps estimé : 8h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 15€/mois.', long_description_en = E'Quick Base is no-code application development platform. Starting at €15/month. Most relevant for manager-dsi and data-analyst.\n\nWhat sets Quick Base apart: specialized in application development, and professional interface. Estimated time saving: 8h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: price to be verified based on usage. As soon as the tool saves you more than €15/month.' WHERE slug = 'quick-base';
UPDATE tools SET long_description = E'ResponseTap, c''est logiciel de suivi des appels pour les marketers. À partir de 15€/mois. Particulièrement pertinent pour les ecommercant.\n\nCe qui distingue ResponseTap : spécialisé en call tracking, et interface professionnelle. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 15€/mois.', long_description_en = E'ResponseTap is call tracking software for marketers. Starting at €15/month. Most relevant for ecommercant.\n\nWhat sets ResponseTap apart: specialized in call tracking, and professional interface. Estimated time saving: 3h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: price to be verified based on usage. As soon as the tool saves you more than €15/month.' WHERE slug = 'responsetap';
UPDATE tools SET long_description = E'La Growth Machine, c''est automatisation multi-canal LinkedIn + Email. À partir de 60€/mois.\n\nCe qui distingue La Growth Machine : multi-canal natif (LinkedIn + Email + Twitter). Ajoutez à ça enrichissement de données intégré, et éditeur de séquences visuel. Pour les usages intensifs : entreprise française (support FR). Cas d''usage typique : automatiser la prospection LinkedIn + Email. On l''utilise aussi pour enrichir des contacts depuis LinkedIn.\n\nÀ garder si : prospection multi-canal active ou budget outbound > 100€/mois. À éviter si : prospection occasionnelle ou budget limité. Point de friction : prix élevé (60€/mois minimum). Rentable si vous signez 1+ client par mois grâce aux séquences.', long_description_en = E'La Growth Machine is multi-channel LinkedIn + Email automation. Starting at €60/month.' WHERE slug = 'la-growth-machine';
UPDATE tools SET long_description = E'Superhuman, c''est l''expérience email la plus rapide au monde. À partir de 25.98€/mois. Particulièrement pertinent pour les fondateurs SaaS et les consultants B2B.\n\nCe qui distingue Superhuman : vitesse fulgurante : tout se fait au clavier. Ajoutez à ça suivi d''ouverture des emails (read receipts), et remind Me : rappel automatique si pas de réponse. Pour les usages intensifs : split Inbox : trier automatiquement vos emails. Cas d''usage typique : prospection : suivre l''ouverture de vos emails commerciaux. On l''utilise aussi pour suivi client : rappels automatiques pour les emails sans réponse. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : vous recevez +50 vrais emails par jour ou l''email est votre outil de travail principal. À éviter si : vous avez moins de 10 emails par jour ou le prix (30$/mois) vous choque. Point de friction : prix élevé : 30€/mois. Dès que l''email devient votre goulot d''étranglement principal.', long_description_en = E'Superhuman is the fastest email experience in the world. Starting at €25.98/month. Most relevant for SaaS founders and B2B consultants.\n\nWhat sets Superhuman apart: blazing speed: everything is done via keyboard. Add to that email tracking (read receipts), and remind Me: automatic reminders if there is no response. For power users: split Inbox: automatically sort your emails. Typical use case: prospecting: track the opening of your sales emails. Also useful for customer follow-up: automatic reminders for unanswered emails. Estimated time saving: 3h/month with regular use.\n\nKeep it if: you receive +50 real emails per day or email is your primary work tool. Skip it if: you have fewer than 10 emails per day or the price ($30/month) is a shock to you. Main friction point: high price: 30€/month. As soon as email becomes your primary bottleneck.' WHERE slug = 'superhuman';
UPDATE tools SET long_description = E'respond.io, c''est logiciel de messagerie alimenté par l’IA pour entreprises B2C. À partir de 20€/mois. Particulièrement pertinent pour les ecommercant et les fondateurs SaaS.\n\nCe qui distingue respond.io : spécialisé en customer messaging, et interface professionnelle. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 20€/mois.', long_description_en = E'respond.io is aI-powered messaging software for B2C businesses. Starting at €20/month. Most relevant for ecommercant and SaaS founders.\n\nWhat sets respond.io apart: specialized in customer messaging, and professional interface. Estimated time saving: 3h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: pricing to check based on usage. As soon as the tool saves you more than €20/month.' WHERE slug = 'respond-io';
UPDATE tools SET long_description = E'Proposify, c''est création de propositions commerciales professionnelles. À partir de 35€/mois.\n\nCe qui distingue Proposify : templates professionnels personnalisables. Ajoutez à ça suivi en temps réel (qui a lu quoi), et signature électronique intégrée. Pour les usages intensifs : analytics d''engagement par section. Cas d''usage typique : créer des propositions commerciales interactives. On l''utilise aussi pour suivre l''engagement des prospects sur les devis.\n\nÀ garder si : 5+ propositions par mois ou cycle de vente B2B. À éviter si : 1-2 devis par mois ou devis simples en 1 page. Point de friction : prix élevé pour les solopreneurs. Rentable dès 5+ propositions commerciales par mois.', long_description_en = E'Proposify is professional commercial proposals. Starting at €35/month.' WHERE slug = 'proposify';
UPDATE tools SET long_description = E'Activepieces, c''est automatisation open-source alternative à Zapier. La version de base est gratuite, avec des options payantes pour aller plus loin.\n\nCe qui distingue Activepieces : open-source et self-hostable. Ajoutez à ça interface visuelle moderne, et communauté active et croissante. Pour les usages intensifs : gratuit en self-hosted. Cas d''usage typique : héberger ses automatisations en propre. On l''utilise aussi pour remplacer Zapier/Make sans dépendance cloud.\n\nÀ garder si : profil technique, à l''aise avec le self-hosting ou souveraineté des données importante. À éviter si : pas de compétences DevOps ou besoin de fiabilité maximale. Point de friction : moins d''intégrations que Zapier/Make. Gratuit en self-hosted — à tester si vous êtes technique et que Zapier est trop cher.', long_description_en = E'Activepieces is open-source automation alternative to Zapier. Core features are free, with paid plans for advanced use.' WHERE slug = 'activepieces';
UPDATE tools SET long_description = E'Cal.com, c''est l''alternative Open Source et flexible à Calendly. À partir de 10.39€/mois. Particulièrement pertinent pour les consultants B2B et les coach-formateur.\n\nCe qui distingue Cal.com : gratuit avec types de réunions illimités (vs 1 chez Calendly). Ajoutez à ça open-source : possibilité d''auto-héberger, et personnalisation complète du branding. Pour les usages intensifs : intégrations avec Zoom, Google Meet, Teams. Cas d''usage typique : consultants : permettre aux prospects de réserver plusieurs types de réunions (découverte, suivi, urgence). On l''utilise aussi pour coachs : gérer les prises de rendez-vous pour différents services. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : vous voulez une maîtrise totale de vos données ou vous voulez un design ultra-minimaliste. À éviter si : vous voulez juste que ça marche sans réfléchir (Calendly est plus simple). Point de friction : interface moins polie que Calendly. Si Calendly vous frustre par ses limitations de design ou de fonctionnalités.', long_description_en = E'Cal.com is the open-source and flexible alternative to Calendly. Starting at €10.39/month. Most relevant for B2B consultants and coach-formateur.\n\nWhat sets Cal.com apart: free with unlimited meeting types (vs 1 for Calendly). Add to that open-source: self-hosting possibility, and full branding customization. For power users: integrations with Zoom, Google Meet, Teams. Typical use case: consultants: allow prospects to book multiple meeting types (discovery, follow-up, urgent). Also useful for coaches: manage appointment bookings for different services. Estimated time saving: 3h/month with regular use.\n\nKeep it if: you want total control over your data or you want an ultra-minimalist design. Skip it if: vous voulez juste que ça marche sans réfléchir (Calendly est plus simple). Main friction point: interface less polished than Calendly. If Calendly frustrates you with its design or feature limitations.' WHERE slug = 'cal-com';
UPDATE tools SET long_description = E'Dubsado, c''est suite de gestion d’entreprise pour créatifs (contrats. La version de base est gratuite, avec des options payantes pour aller plus loin. Particulièrement pertinent pour les consultants B2B et les fondateurs SaaS.\n\nCe qui distingue Dubsado : spécialisé en business management, et interface professionnelle. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Gratuit, à garder si utile.', long_description_en = E'Dubsado is business management suite for creatives (contracts, invoices, automation). Core features are free, with paid plans for advanced use. Most relevant for B2B consultants and SaaS founders.\n\nWhat sets Dubsado apart: specialized in business management, and professional interface. Estimated time saving: 3h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: price to be verified based on usage. Free, to keep if useful.' WHERE slug = 'dubsado';
UPDATE tools SET long_description = E'Better Proposals, c''est propositions commerciales avec suivi et signatures. À partir de 19€/mois.\n\nCe qui distingue Better Proposals : propositions web (pas PDF) — meilleure expérience. Ajoutez à ça paiement intégré (Stripe, PayPal), et templates modernes et responsive. Pour les usages intensifs : prix plus accessible que Proposify. Cas d''usage typique : envoyer des propositions web interactives. On l''utilise aussi pour collecter les paiements à la signature.\n\nÀ garder si : propositions clients régulières ou besoin de paiement intégré. À éviter si : besoin de propositions PDF traditionnelles ou 1-2 devis par mois. Point de friction : moins de personnalisation que Proposify. Bon choix dès 3+ propositions par mois avec des clients modernes.', long_description_en = E'Better Proposals is commercial proposals with tracking and signatures. Starting at €19/month.' WHERE slug = 'better-proposals';
UPDATE tools SET long_description = E'Cargo Site, c''est portfolios créatifs avec design expérimental. À partir de 13€/mois.\n\nCe qui distingue Cargo Site : templates créatifs et expérimentaux. Ajoutez à ça communauté de designers reconnue, et typographie et animations avancées. Pour les usages intensifs : effet galerie d''art numérique. Cas d''usage typique : créer un portfolio artistique unique. On l''utilise aussi pour présenter des projets créatifs avec impact visuel.\n\nÀ garder si : designer ou artiste cherchant un portfolio unique ou esthétique et originalité prioritaires. À éviter si : site business classique ou sEO et performance critiques. Point de friction : pas pour les sites fonctionnels/business. Le bon choix si votre portfolio EST votre produit et doit impressionner visuellement.', long_description_en = E'Cargo Site is creative portfolios with experimental design. Starting at €13/month.' WHERE slug = 'cargo-site';
UPDATE tools SET long_description = E'ConvertKit Analytics, c''est suivi de performance intégré ConvertKit. La version de base est gratuite, avec des options payantes pour aller plus loin.\n\nCe qui distingue ConvertKit Analytics : intégré nativement à ConvertKit. Ajoutez à ça suivi des revenus de produits numériques, et interface claire et lisible. Pour les usages intensifs : aucune configuration nécessaire. Cas d''usage typique : suivre les performances de chaque email. On l''utilise aussi pour mesurer les revenus des produits numériques.\n\nÀ garder si : déjà sur ConvertKit ou vente de produits numériques. À éviter si : pas sur ConvertKit ou besoin d''analytics poussés. Point de friction : uniquement pour ConvertKit. Gratuit avec ConvertKit — consultez au moins une fois par semaine.', long_description_en = E'ConvertKit Analytics is integrated ConvertKit performance tracking. Core features are free, with paid plans for advanced use.' WHERE slug = 'convertkit-analytics';
UPDATE tools SET long_description = E'Fig, c''est autocomplétion IDE pour le terminal. La version de base est gratuite, avec des options payantes pour aller plus loin.\n\nCe qui distingue Fig : autocomplétion visuelle puissante. Ajoutez à ça fonctionne avec votre terminal existant, et support de 500+ CLI. Pour les usages intensifs : suggestions contextuelles intelligentes. Cas d''usage typique : autocompléter les commandes git complexes. On l''utilise aussi pour découvrir les flags disponibles d''une CLI.\n\nÀ garder si : usage intensif de CLI variées ou macOS. À éviter si : déjà sur Warp (inclut l''autocomplétion) ou windows. Point de friction : racheté par AWS (évolution incertaine). Gratuit — à installer si vous tapez 50+ commandes par jour.', long_description_en = E'Fig is iDE autocomplete for the terminal. Core features are free, with paid plans for advanced use.' WHERE slug = 'fig-terminal';
UPDATE tools SET long_description = E'RocketLink, c''est raccourcisseur d’URL avec reciblage publicitaire. À partir de 15€/mois. Particulièrement pertinent pour les ecommercant et les fondateurs SaaS.\n\nCe qui distingue RocketLink : spécialisé en link shortener, et interface professionnelle. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 15€/mois.', long_description_en = E'RocketLink is uRL shortener with ad retargeting. Starting at €15/month. Most relevant for ecommercant and SaaS founders.\n\nWhat sets RocketLink apart: specialized in link shortener, and professional interface. Estimated time saving: 3h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: price to be verified based on usage. As soon as the tool saves you more than €15/month.' WHERE slug = 'rocketlink';
UPDATE tools SET long_description = E'Salesforce, c''est logiciel de gestion de la relation client et solutions cloud. À partir de 15€/mois. Particulièrement pertinent pour les manager-dsi et les fondateurs SaaS.\n\nCe qui distingue Salesforce : spécialisé en CRM, et interface professionnelle. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 15€/mois.', long_description_en = E'Salesforce is customer relationship management software and cloud solutions. Starting at €15/month. Most relevant for manager-dsi and SaaS founders.\n\nWhat sets Salesforce apart: specialized in CRM, and professional interface. Estimated time saving: 3h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: price to be verified based on usage. As soon as the tool saves you more than €15/month.' WHERE slug = 'salesforce';
UPDATE tools SET long_description = E'SaneBox, c''est l''IA qui trie vos emails et vous fait gagner 12h par mois. À partir de 6.06€/mois. Particulièrement pertinent pour les consultants B2B et les manager-dsi.\n\nGain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : vous recevez +50 emails par jour ou votre boîte mail est votre goulot d''étranglement. À éviter si : vous recevez moins de 20 emails par jour ou vous maîtrisez déjà parfaitement les filtres Gmail. Dès que l''email devient une source de stress quotidien et que vous ratez des messages importants. Alternative gratuite à considérer : gmail.', long_description_en = E'SaneBox is the AI that sorts your emails and saves you 12 hours per month. Starting at €6.06/month. Most relevant for B2B consultants and manager-dsi.\n\nEstimated time saving: 3h/month with regular use.\n\nKeep it if: you receive +50 emails per day or your inbox is your bottleneck. Skip it if: you receive fewer than 20 emails per day or you already have a perfect mastery of Gmail filters. As soon as email becomes a daily source of stress and you start missing important messages. Free alternative worth considering: gmail.' WHERE slug = 'sanebox';
UPDATE tools SET long_description = E'Ruby, c''est standard téléphonique virtuel et chat en direct pour entreprises. La version de base est gratuite, avec des options payantes pour aller plus loin. Particulièrement pertinent pour les consultants B2B et les fondateurs SaaS.\n\nCe qui distingue Ruby : spécialisé en virtual receptionist, et interface professionnelle. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Gratuit, à garder si utile.', long_description_en = E'Ruby is virtual phone system and live chat for businesses. Core features are free, with paid plans for advanced use. Most relevant for B2B consultants and SaaS founders.\n\nWhat sets Ruby apart: specialized in virtual receptionist services, and professional interface. Estimated time saving: 3h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: prices to be verified based on usage. Free; keep it if it''s useful.' WHERE slug = 'ruby';
UPDATE tools SET long_description = E'Roam Research, c''est prise de notes en réseau avec liens bidirectionnels. À partir de 15€/mois.\n\nCe qui distingue Roam Research : liens bidirectionnels natifs. Ajoutez à ça graphe de connaissances visuel, et outliner puissant. Pour les usages intensifs : communauté intellectuelle active. Cas d''usage typique : construire une base de connaissances personnelle. On l''utilise aussi pour connecter des idées entre projets et clients.\n\nÀ garder si : prise de notes intensive (recherche, consulting) ou besoin de connecter des idées entre projets. À éviter si : notes simples et linéaires ou besoin d''une interface visuelle. Point de friction : courbe d''apprentissage significative. Justifié si vous prenez 30+ notes par semaine et avez besoin de les relier.', long_description_en = E'Roam Research is networked note-taking with bidirectional links. Starting at €15/month.' WHERE slug = 'roam-research';
UPDATE tools SET long_description = E'Cleanvoice, c''est nettoyage audio automatique par IA. À partir de 10€/mois.\n\nCe qui distingue Cleanvoice : nettoyage audio automatique par IA. Ajoutez à ça suppression des hésitations et silences, et traitement en batch. Pour les usages intensifs : supporte le français et l''anglais. Cas d''usage typique : nettoyer un épisode de podcast en 1 clic. On l''utilise aussi pour supprimer le bruit de fond des interviews.\n\nÀ garder si : production audio régulière ou temps de post-production à réduire. À éviter si : production audio rare ou déjà un bon setup micro. Point de friction : fonction unique (pas d''édition). Rentable dès 2+ heures d''audio à nettoyer par mois.', long_description_en = E'Cleanvoice is automatic AI audio cleaning. Starting at €10/month.' WHERE slug = 'cleanvoice';
UPDATE tools SET long_description = E'Beehiiv Analytics, c''est métriques avancées pour newsletters Beehiiv. La version de base est gratuite, avec des options payantes pour aller plus loin.\n\nCe qui distingue Beehiiv Analytics : inclus dans Beehiiv (pas de coût supplémentaire). Ajoutez à ça métriques détaillées et visuelles, et attribution et suivi des revenus. Pour les usages intensifs : segmentation avancée. Cas d''usage typique : analyser les taux d''ouverture par segment. On l''utilise aussi pour suivre la croissance des abonnés.\n\nÀ garder si : déjà sur Beehiiv ou newsletter comme canal principal. À éviter si : pas sur Beehiiv ou newsletter occasionnelle. Point de friction : uniquement pour les utilisateurs Beehiiv. Gratuit avec Beehiiv — exploiter au maximum les données disponibles.', long_description_en = E'Beehiiv Analytics is advanced metrics for Beehiiv newsletters. Core features are free, with paid plans for advanced use.' WHERE slug = 'beehiiv-analytics';
UPDATE tools SET long_description = E'Warp, c''est terminal moderne avec IA intégrée pour développeurs. La version de base est gratuite, avec des options payantes pour aller plus loin.\n\nCe qui distingue Warp : iA intégrée pour expliquer/générer des commandes. Ajoutez à ça blocs de commande éditables, et historique searchable et partageable. Pour les usages intensifs : vitesse native (Rust). Cas d''usage typique : rechercher dans l''historique des commandes. On l''utilise aussi pour demander à l''IA de générer une commande.\n\nÀ garder si : 2h+ par jour dans le terminal ou envie d''IA dans le terminal. À éviter si : windows ou usage terminal occasionnel. Point de friction : macOS et Linux uniquement (pas Windows). Gratuit — à essayer si vous passez du temps significatif dans le terminal.', long_description_en = E'Warp is modern terminal with built-in AI for developers. Core features are free, with paid plans for advanced use.' WHERE slug = 'warp';
UPDATE tools SET long_description = E'Trello, c''est le Kanban visuel pour organiser ses projets sans complexité. À partir de 8.66€/mois. Particulièrement pertinent pour les consultants B2B et les graphiste-da.\n\nGain de temps estimé : 4h/mois pour un usage régulier.\n\nÀ garder si : vous aimez visualiser vos tâches en colonnes (To Do, Doing, Done) ou vous gérez 2-5 projets simultanément. À éviter si : vous avez besoin de fonctions avancées (Gantt, dépendances) ou vous gérez +10 projets complexes (prenez Asana ou ClickUp). Dès que vous avez +2 projets actifs et que Notion devient trop lourd pour la gestion de tâches. Alternative gratuite à considérer : notion.', long_description_en = E'Trello is visual Kanban for organizing your projects without the complexity. Starting at €8.66/month. Most relevant for B2B consultants and graphiste-da.\n\nEstimated time saving: 4h/month with regular use.\n\nKeep it if: you like to visualize your tasks in columns (To Do, Doing, Done) or you manage 2-5 projects simultaneously. Skip it if: you need advanced features (Gantt, dependencies) or you manage 10+ complex projects (choose Asana or ClickUp). As soon as you have more than 2 active projects and Notion becomes too cumbersome for task management. Free alternative worth considering: notion.' WHERE slug = 'trello';
UPDATE tools SET long_description = E'Sellfy, c''est plateforme e-commerce pour créer des boutiques en ligne. À partir de 20€/mois. Particulièrement pertinent pour les fondateurs SaaS et les developpeur-solo.\n\nCe qui distingue Sellfy : spécialisé en online store platform, et interface professionnelle. Gain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 20€/mois.', long_description_en = E'Sellfy is e-commerce platform for creating online stores. Starting at €20/month. Most relevant for SaaS founders and solo developers.\n\nWhat sets Sellfy apart: specialized online store platform, and professional interface. Estimated time saving: 5h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: price to be verified based on usage. As soon as the tool saves you more than €20/month.' WHERE slug = 'sellfy';
UPDATE tools SET long_description = E'Shopify, c''est plateforme e-commerce pour boutiques en ligne et points de vente. À partir de 25.11€/mois. Particulièrement pertinent pour les ecommercant.\n\nCe qui distingue Shopify : spécialisé en e-commerce platform, et interface professionnelle. Gain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 15€/mois.', long_description_en = E'Shopify is e-commerce platform for online stores and points of sale. Starting at €25.11/month. Most relevant for ecommercant.\n\nWhat sets Shopify apart: specialized in e-commerce platform, and professional interface. Estimated time saving: 5h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: price to check according to usage. As soon as the tool saves you more than €15/month.' WHERE slug = 'shopify';
UPDATE tools SET long_description = E'Pabbly Connect, c''est automatisation sans code à prix fixe illimité. À partir de 16€/mois.\n\nCe qui distingue Pabbly Connect : prix fixe sans limite de tâches. Ajoutez à ça workflows illimités, et interface drag-and-drop. Pour les usages intensifs : bon rapport qualité/prix. Cas d''usage typique : automatiser les flux CRM + email. On l''utilise aussi pour synchroniser des données entre apps.\n\nÀ garder si : budget Zapier devenu trop élevé ou volume important de tâches automatisées. À éviter si : besoin d''intégrations rares ou préférence pour la fiabilité maximale. Point de friction : moins d''intégrations que Zapier (1000 vs 6000+). Économique dès que Zapier dépasse 30$/mois.', long_description_en = E'Pabbly Connect is no-code automation at unlimited flat price. Starting at €16/month.' WHERE slug = 'pabbly-connect';
UPDATE tools SET long_description = E'Mailchimp, c''est l''incontournable de l''email marketing pour petites listes. À partir de 11.26€/mois. Particulièrement pertinent pour les ecommercant et les fondateurs SaaS.\n\nGain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : vous lancez votre première newsletter ou vous avez moins de 500 abonnés. À éviter si : vous avez +1000 abonnés (devient cher, prenez GetResponse) ou vous êtes créateur de contenu (prenez ConvertKit). Dès que vous voulez envoyer votre première newsletter et que vous avez moins de 500 contacts. Alternative gratuite à considérer : brevo.', long_description_en = E'Mailchimp is the essential email marketing tool for small lists. Starting at €11.26/month. Most relevant for ecommercant and SaaS founders.\n\nEstimated time saving: 3h/month with regular use.\n\nKeep it if: you are launching your first newsletter or you have fewer than 500 subscribers. Skip it if: you have +1000 subscribers (becomes expensive, choose GetResponse) or you are a content creator (choose ConvertKit). As soon as you want to send your first newsletter and you have fewer than 500 contacts. Free alternative worth considering: brevo.' WHERE slug = 'mailchimp';
UPDATE tools SET long_description = E'SEMrush, c''est plateforme SaaS de marketing digital et SEO. À partir de 20€/mois. Particulièrement pertinent pour les ecommercant et les fondateurs SaaS.\n\nCe qui distingue SEMrush : spécialisé en SEO, et interface professionnelle. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 20€/mois.', long_description_en = E'SEMrush is digital marketing and SEO SaaS platform. Starting at €20/month. Most relevant for ecommercant and SaaS founders.\n\nWhat sets SEMrush apart: specialized in SEO, and professional interface. Estimated time saving: 3h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: price to be verified based on usage. As soon as the tool saves you more than €20/month.' WHERE slug = 'semrush';
UPDATE tools SET long_description = E'Zed, c''est éditeur de code haute performance avec collaboration. La version de base est gratuite, avec des options payantes pour aller plus loin.\n\nCe qui distingue Zed : performance exceptionnelle (Rust). Ajoutez à ça démarrage quasi-instantané, et collaboration en temps réel native. Pour les usages intensifs : interface épurée et moderne. Cas d''usage typique : éditer du code sur de gros projets sans lag. On l''utilise aussi pour pair-programmer en temps réel.\n\nÀ garder si : vS Code trop lent sur vos projets ou besoin de collaboration en temps réel. À éviter si : dépendance à des extensions VS Code spécifiques ou windows (pour l''instant). Point de friction : écosystème d''extensions naissant. Gratuit — à tester si VS Code ralentit sur vos projets.', long_description_en = E'Zed is high-performance code editor with collaboration. Core features are free, with paid plans for advanced use.' WHERE slug = 'zed';
UPDATE tools SET long_description = E'HoneyBook, c''est gestion de projets clients et facturation créative. À partir de 16€/mois. Particulièrement pertinent pour les consultants B2B et les photographe.\n\nCe qui distingue HoneyBook : workflow client de bout en bout. Ajoutez à ça contrats et paiements intégrés, et templates professionnels. Pour les usages intensifs : interface moderne et intuitive. Cas d''usage typique : envoyer des propositions avec paiement intégré. On l''utilise aussi pour automatiser le suivi client. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : créatif ou consultant avec flux client récurrent ou besoin de contrats + paiements intégrés. À éviter si : marché exclusivement français ou besoin d''un CRM puissant. Point de friction : principalement anglophone. Rentable dès 3+ projets clients par mois.', long_description_en = E'HoneyBook is client management software for small businesses (CRM). Starting at €16/month. Most relevant for B2B consultants and photographe.\n\nWhat sets HoneyBook apart: specialized in client management, and professional interface. Estimated time saving: 3h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: price to be verified depending on usage. Free, keep it if it''s useful.' WHERE slug = 'honeybook';
UPDATE tools SET long_description = E'ShopHero, c''est plateforme de gestion e-commerce et supply chain. À partir de 10€/mois. Particulièrement pertinent pour les fondateurs SaaS et les developpeur-solo.\n\nCe qui distingue ShopHero : spécialisé en e-commerce platform, et interface professionnelle. Gain de temps estimé : 5h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 10€/mois.', long_description_en = E'ShopHero is e-commerce and supply chain management platform. Starting at €10/month. Most relevant for SaaS founders and solo developers.\n\nWhat sets ShopHero apart: specialized in e-commerce platform, and professional interface. Estimated time saving: 5h/month with regular use.\n\nKeep it if: regular usage or essential features. Skip it if: occasional use or tight budget. Main friction point: price to be verified based on usage. As soon as the tool saves you more than €10/month.' WHERE slug = 'shophero';
UPDATE tools SET long_description = E'SMTP.com, c''est service d’emails transactionnels et API avec haute délivrabilité. La version de base est gratuite, avec des options payantes pour aller plus loin. Particulièrement pertinent pour les developpeur-solo et les fondateurs SaaS.\n\nCe qui distingue SMTP.com : spécialisé en email delivery, et interface professionnelle. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Gratuit, à garder si utile.', long_description_en = E'SMTP.com is transactional email service and API with high deliverability. Core features are free, with paid plans for advanced use. Most relevant for solo developers and SaaS founders.\n\nWhat sets SMTP.com apart: specialized in email delivery, and professional interface. Estimated time saving: 3h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: pricing to be verified based on usage. Free tool, worth keeping if it proves useful.' WHERE slug = 'smtp-com';
UPDATE tools SET long_description = E'Toggl Track, c''est le tracker de temps pour facturer au juste prix. À partir de 7.79€/mois. Particulièrement pertinent pour les consultants B2B et les graphiste-da.\n\nGain de temps estimé : 2h/mois pour un usage régulier.\n\nÀ garder si : vous facturez au temps passé ou vous voulez savoir où part votre temps. À éviter si : vous facturez au forfait uniquement ou vous avez un seul client récurrent. Dès que vous facturez au temps passé ou que vous voulez optimiser votre rentabilité.', long_description_en = E'Toggl Track is the time tracker for billing at the right price. Starting at €7.79/month. Most relevant for B2B consultants and graphiste-da.\n\nEstimated time saving: 2h/month with regular use.\n\nKeep it if: you bill based on time spent or you want to know where your time goes. Skip it if: you charge on a flat-fee basis only or you have only one recurring client. As soon as you bill by time spent or want to optimize your profitability.' WHERE slug = 'toggl';
UPDATE tools SET long_description = E'SmartSuite, c''est plateforme collaborative de gestion du travail pour équipes. À partir de 20€/mois. Particulièrement pertinent pour les manager-dsi et les fondateurs SaaS.\n\nCe qui distingue SmartSuite : spécialisé en work management, et interface professionnelle. Gain de temps estimé : 3h/mois pour un usage régulier.\n\nÀ garder si : usage régulier ou fonctionnalités essentielles. À éviter si : usage ponctuel ou budget serré. Point de friction : prix à vérifier selon usage. Dès que l''outil vous fait gagner plus de 20€/mois.', long_description_en = E'SmartSuite is collaborative work management platform for teams. Starting at €20/month. Most relevant for manager-dsi and SaaS founders.\n\nWhat sets SmartSuite apart: specialized in work management, and professional interface. Estimated time saving: 3h/month with regular use.\n\nKeep it if: regular use or essential features. Skip it if: occasional use or tight budget. Main friction point: pricing to be verified based on usage. As soon as the tool saves you more than €20/month.' WHERE slug = 'smartsuite';

COMMIT;
